insert into public.categories(name,slug,description,sort_order) values ('Pulseras','pulseras','Diseños tejidos a mano',1),('Collares','collares','Piezas para llevar cerca',2),('Aretes','aretes','Detalles ligeros y coloridos',3),('Tobilleras','tobilleras','Color para cada paso',4),('Anillos','anillos','Pequeñas piezas con carácter',5),('Llaveros','llaveros','Compañeros cotidianos',6),('Accesorios','accesorios','Detalles CAMARI',7),('Decoración','decoracion','Arte para tus espacios',8),('Personalizados','personalizados','Creado especialmente para ti',9) on conflict(slug) do nothing;
insert into public.products(name,slug,short_description,description,price,compare_at_price,stock,category_id,published,featured,is_new,on_sale,is_unique,customizable) select x.name,x.slug,'PRODUCTO DEMO · Elimínalo o edítalo desde /admin',x.description,x.price,x.compare_price,x.stock,c.id,true,x.featured,x.is_new,x.on_sale,x.is_unique,true from(values ('Pulsera Aurora','pulsera-aurora-demo','PRODUCTO DEMO. Tejido cálido inspirado en el amanecer.',25000::numeric,null::numeric,8,true,true,false,false,'pulseras'),('Collar Tierra','collar-tierra-demo','PRODUCTO DEMO. Tonos naturales y textura delicada.',52000,null,4,true,false,false,true,'collares'),('Pulsera Horizonte','pulsera-horizonte-demo','PRODUCTO DEMO. Una línea de color para llevar contigo.',30000,35000,6,false,false,true,false,'pulseras'),('Aretes Luna','aretes-luna-demo','PRODUCTO DEMO. Ligeros, sutiles y luminosos.',38000,null,3,true,true,false,true,'aretes'),('Tobillera Brisa','tobillera-brisa-demo','PRODUCTO DEMO. Movimiento y color en cada paso.',28000,null,9,false,true,false,false,'tobilleras'),('Llavero Prisma','llavero-prisma-demo','PRODUCTO DEMO. Un acento único para tus llaves.',22000,null,10,false,false,false,false,'llaveros')) as x(name,slug,description,price,compare_price,stock,featured,is_new,on_sale,is_unique,category_slug) join public.categories c on c.slug=x.category_slug on conflict(slug) do nothing;
insert into public.testimonials(name,comment,rating,published,sort_order) values('Cliente demo','TESTIMONIO DEMO. La pieza se siente única y llegó con un empaque precioso.',5,true,1);
